# Teaching app skeleton --------------------------------------------------
# Reusable Shiny shell for hands-on training sessions.
#
# Design distilled from the CATA Science platform (2025-08-12) and the
# GHLC course app (2025-07-22), keeping the patterns that proved useful:
#   - lessons are plain markdown files in lessons/ — drop a file in and it
#     appears as a tab, no code change needed
#   - one uploaded dataset drives all hands-on panels
#   - upload wrapped in tryCatch with user-facing notifications
#   - dynamic UI built from the data's actual structure
#
# To adapt for a session: replace the files in lessons/, optionally drop a
# default dataset into data/, and edit APP_TITLE.

library(tidyverse)
library(shiny)
library(bslib)
library(DT)
library(rio)
library(naniar)
library(markdown)

source("teaching-helpers.R")

# kNN imputation needs VIM, which has no WebAssembly build — in the
# standalone (shinylive) version the option degrades to mean/median only.
has_vim <- FALSE  # VIM has no WebAssembly build

APP_TITLE <- "DSI Training — Hands-on Companion"

# Lessons: every lessons/*.md becomes a nav tab, ordered by file name
# (prefix with 01-, 02-, ... to control order; first line "# Title" is the
# tab label).
lesson_files <- sort(list.files("lessons", pattern = "\\.md$", full.names = TRUE))

lesson_title <- function(path) {
  first <- readLines(path, n = 1, warn = FALSE)
  title <- sub("^#\\s*", "", first)
  if (nzchar(title)) title else basename(path)
}

lesson_panels <- lapply(lesson_files, function(path) {
  nav_panel(
    title = lesson_title(path),
    card(includeMarkdown(path))
  )
})


# UI ----------------------------------------------------------------------

ui <- page_navbar(
  title = APP_TITLE,
  theme = bs_theme(bootswatch = "yeti"),

  nav_panel(
    title = "Data",
    layout_sidebar(
      sidebar = sidebar(
        fileInput("file", "Upload a dataset (csv / xlsx)",
                  accept = c(".csv", ".xlsx")),
        helpText("Or work with the built-in example."),
        actionButton("load_example", "Load example data")
      ),
      card(
        card_header("Preview"),
        DTOutput("preview")
      ),
      card(
        card_header("Structure"),
        verbatimTextOutput("structure")
      )
    )
  ),

  nav_panel(
    title = "Missing data",
    layout_sidebar(
      sidebar = sidebar(
        checkboxGroupInput("miss_vars", "Variables to impute", choices = NULL),
        radioButtons("miss_method", "Method",
                     c("Mean" = "mean", "Median" = "median",
                       if (has_vim) c("kNN" = "knn"))),
        actionButton("apply_impute", "Apply imputation", class = "btn-primary")
      ),
      card(
        card_header("Recognise before you repair"),
        plotOutput("miss_plot", height = "320px"),
        verbatimTextOutput("miss_summary")
      )
    )
  ),

  nav_panel(
    title = "Outliers",
    layout_sidebar(
      sidebar = sidebar(
        selectInput("out_var", "Numeric variable", choices = NULL),
        actionButton("apply_winsor", "Winsorize (IQR fences)",
                     class = "btn-primary")
      ),
      card(plotOutput("out_plot", height = "360px"))
    )
  ),

  !!!lesson_panels,

  nav_spacer(),
  nav_item(tags$small("WHO WPRO / DSI · training-modules"))
)


# Server --------------------------------------------------------------------

server <- function(input, output, session) {

  df <- reactiveVal(NULL)

  observeEvent(input$file, {
    tryCatch(
      df(as_tibble(import(input$file$datapath))),
      error = function(e) {
        showNotification(
          paste("Could not import the file:", conditionMessage(e)),
          type = "error"
        )
      }
    )
  })

  observeEvent(input$load_example, {
    df(as_tibble(import("data/cat-dirty-data.xlsx")))
    showNotification("Example loaded: the cat-café dataset.", type = "message")
  })

  output$preview <- renderDT({
    req(df())
    dtable1(df())
  })

  output$structure <- renderPrint({
    req(df())
    glimpse(df())
  })

  # Missing data ----
  observe({
    req(df())
    vars <- miss_var_which(df())
    updateCheckboxGroupInput(session, "miss_vars",
                             choices = vars, selected = NULL)
  })

  output$miss_plot <- renderPlot({
    req(df())
    vis_miss(df())
  })

  output$miss_summary <- renderPrint({
    req(df())
    has_missing(df())
  })

  observeEvent(input$apply_impute, {
    req(df(), input$miss_vars)
    data <- df()
    for (v in input$miss_vars) {
      if (!is.numeric(data[[v]])) next
      data[[v]] <- switch(
        input$miss_method,
        mean = replace_na(data[[v]], mean(data[[v]], na.rm = TRUE)),
        median = replace_na(data[[v]], median(data[[v]], na.rm = TRUE))
      )
    }
    df(data)
    showNotification("Imputation applied.", type = "message")
  })

  # Outliers ----
  observe({
    req(df())
    nums <- names(select(df(), where(is.numeric)))
    updateSelectInput(session, "out_var", choices = nums)
  })

  output$out_plot <- renderPlot({
    req(df(), input$out_var)
    ggplot(df(), aes(y = .data[[input$out_var]])) +
      geom_boxplot(fill = "cadetblue", staplewidth = .5) +
      labs(title = paste("Distribution of", input$out_var), x = "") +
      theme_minimal(base_size = 14)
  })

  observeEvent(input$apply_winsor, {
    req(df(), input$out_var)
    data <- df()
    data[[input$out_var]] <- winsorize(data[[input$out_var]])
    df(data)
    showNotification("Winsorized at the IQR fences.", type = "message")
  })
}

shinyApp(ui, server)
